WFJ.Data.add("gossip", {
  ["9002d728d2b5825a"] = { "La Madre Terra custodisce molti segreti e Brek Stonehoof può aiutarti a scoprirne alcuni. Lo troverai sull'altura inferiore, alla Stonehoof Geology.", "." },
  ["9004a8f2c5d6ab80"] = { "Perché dovrei andarci piano, se funziona?", "." },
  ["900a841ecae88141"] = { "L'anziano Brightspear si trova a vagare tra le rovine di Kel'Theril, a ⟦Winterspring=Fontefredda⟧.", "." },
  ["900d2b9e41000baa"] = { "E se uno muore, due sorgeranno!", "." },
  ["901095e91f13947d"] = { "Puoi depositare i tuoi beni terreni alla banca di Darnassus, che si trova al centro della nostra splendida città.", "." },
  ["9019e421ded72cf1"] = { "Ecco la classifica finale!\n\nThrall: $2200w\n\nCairne: $2201w\n\nSylvanas: $2202w\n\nTotale ⟦Horde=Orda⟧: $2207w\n\nBolvar: $2203w\n\nMagni: $2204w\n\nTyrande: $2205w\n\nTotale ⟦Alliance=Alleanza⟧: $2206w\n\nL'⟦Horde=Orda⟧ e l'⟦Alliance=Alleanza⟧ hanno pareggiato nel totale dei voti!", "." },
  ["901fcd8587c0e272"] = { "Mi stai prendendo in giro? Mi devi prendere in giro per forza! O quello, o pensi che io sia un pagliaccio qui per divertirti. È questo che pensi? Che sono un pagliaccio? Eh, è così? Pensi che sia un pagliaccio, vero?!", "." },
  ["902909341515db4b"] = { "Le migliori armi delle ⟦Barrens=Savane⟧, qui!", "." },
  ["902c128ce3997242"] = { "Ho finito i tuoi gambali, {name}.", "." },
  ["9035a4e021e3fe7c"] = { "Non ho mai troppo da fare per parlare con <uno/una> <sconosciuto/sconosciuta>! Quasi mai, almeno...", "." },
  ["903a41037df347e6"] = { "Spero che il mio John abbia più fortuna a ⟦Ironforge=Forgiardente⟧. Detesta quei viaggi perché lasciano soli me e i bambini, ma sa che vanno fatti. Ha un cuore d'oro.\n\nCerti anni sono stati più facili di altri, ma questo è stato di gran lunga il più duro. È quasi come se qualcosa nell'aria annunciasse un grande cambiamento. Ma chi può dirlo?", "." },
  ["903c7ab731d4d369"] = { "Pane di ogni tipo! Sfornato oggi. Prendetelo finché dura!", "." },
  ["903ec9c771a5006d"] = { "Circolare, <cittadino/cittadina>. Non c'è niente da vedere.", "." },
  ["904e41e6ad51a614"] = { "Salute, <ragazzo/ragazza>. Sono Grelin Whitebeard. Sono qui per valutare la minaccia rappresentata dal numero crescente di troll nella ⟦Coldridge Valley=Valle Crestafredda⟧. Cosa ho scoperto? È un po' preoccupante...", "." },
  ["905661a9f7f78fe8"] = { "Metti il Barile di Termiti sulla cassa.", "." },
  ["9058364c9a8bcf6d"] = { "Esplosione in arrivo tra 10 secondi!", "." },
  ["905aede8acc92152"] = { "Se vuoi una cosa fatta bene, fattela da te!", "." },
  ["90601709b3805754"] = { "Sei tu l'Earthshaper in grado di creare l'Elementio?", "." },
  ["9067f1f1a77b1b1b"] = { "Corbett, ci sei? Harlan ha bisogno di un altro carico di maglieria. Puoi portarglielo?", "." },
  ["90766a49b751f330"] = { "Va' a nord lungo la strada per Orgrimmar. Puoi chiedere a uno dei grunt là indicazioni per l'istruttore di cucina.", "." },
  ["9077f2c349e5ee93"] = { "Vieni a imparare, eh? Be', potrei avere un lavoretto per te, <pivello/pivella>.", "." },
  ["9081a99972091cac"] = { "Dalla caduta di Dalaran e dalla distruzione di Quel'Thalas, merci di questo tipo sono difficili da trovare. Ma Lucan Cordell e alcuni altri nostri mercanti stanno facendo un ottimo lavoro nell'evadere i nostri ordini con merce di qualità.", "." },
  ["90828eac1f34f7bb"] = { "Cosa potrebbe mai succedere di peggio?", "." },
  ["908c9e5642ffee0c"] = { "Tutti i viaggiatori diretti a Mulgore partano da qui.", "." },
  ["908cdcb262607de9"] = { "Siete giunti troppo lontano per fallire. State indietro, mortali.", "." },
  ["90944d578b640736"] = { "Non ho ancora il grado di Esperto in Erbalismo... posso aiutarti lo stesso nel tuo lavoro?", "." },
  ["9094ef980d3d38b4"] = { "Vorrei solo avere più allievi come te. Non molti si spingono così a fondo in territorio nemico. Saluto il tuo coraggio.", "." },
  ["90955d8b82ea8eb5"] = { "Buliwyf, il maestro d'armi nano alla Timberline Arms di ⟦Ironforge=Forgiardente⟧, insegna armi da pugno, armi da fuoco, asce a una e a due mani e mazze a una e a due mani.\n\nBixi Wobblebonk, la maestra d'armi gnoma alla Timberline Arms di ⟦Ironforge=Forgiardente⟧, insegna balestre, pugnali e armi da lancio.\n\nIlyenia Moonfire, la maestra d'armi elfa della notte, risiede alla ⟦Warrior's Terrace=Terrazza dei Guerrieri⟧ di Darnassus, dove insegna archi, pugnali, armi da pugno, bastoni e armi da lancio.", "." },
  ["90b46559e444f9e5"] = { "Ishnu-alah, <fratello/sorella>. Hai notizie da lontano? Il mio cuore anela a notizie di Teldrassil.", "." },
  ["90b9b44b42aed07d"] = { "Fermati e combatti!", "." },
  ["90bc31a6f593baa0"] = { "Mostrami cosa posso imparare.", "." },
  ["90bc3b52dfe5e7b6"] = { "Il Kirin Tor non ha dato ascolto ai miei avvertimenti! L'⟦Alliance=Alleanza⟧ è una farsa. Arugal è un pazzo sconsiderato.", "." },
  ["90c6ecf997d7ea59"] = { "Al mio fianco, fratelli! Per i Creatori!", "." },
  ["90c855db862e2c03"] = { "Preparatevi. Silverwing è subito dopo la curva.", "." },
  ["90c858e3b4a0a737"] = { "Non ho alcuna prova, Cyrus.", "." },
  ["90e09488e98ffa8d"] = { "Le luci della console sono smorzate e gli indicatori e i quadranti segnano tutti zero: ogni cosa è ferma.", "." },
  ["90e3e7dcbf2d90f0"] = { "Che state facendo? Intrusi!!", "." },
  ["90ec970e3374b90f"] = { "Signora, di' a Plugger che voglio altra della sua birra. Non ne ho mai abbastanza!", "." },
  ["90f01cb4797b578b"] = { "Mi spiace, <fratello/sorella>, ma non venderò i miei raptor a chi non si è dimostrato osannato presso la tribù ⟦Darkspear=Lanciascura⟧. Quando prenderai posizione e ti dimostrerai almeno <osannato/osannata> presso di noi, allora metterò a tua disposizione i miei raptor.", "." },
  ["90f5c60e6709cf0b"] = { "Ora dimostra il tuo valore!", "." },
})
